199	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
200	
201	        // iterate the form control elements and accumulate their values
202	        for (Element el: elements()) {
203	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
